fn main() {
    let mut parser = tree_sitter::Parser::new();
    parser.set_language(&tree_sitter_matlab::LANGUAGE.into()).unwrap();
    let source = b"b.fopen();\ns = serialport('COM3', 9600);\nopengl('data');\nlinprog(x);\nintlinprog(f,A,b);\nbt = bluetooth('x');\nbt.flushinput();\n";
    let tree = parser.parse(source, None).unwrap();
    let mut cursor = tree.walk();
    let mut stack = vec![(tree.root_node(), 0)];
    while let Some((node, depth)) = stack.pop() {
        let text = &source[node.start_byte()..node.end_byte()];
        let text = String::from_utf8_lossy(text);
        println!("{}kind={} name_field={:?} text={:?}", "  ".repeat(depth), node.kind(), node.child_by_field_name("name").map(|n| n.kind()), text);
        let mut children = node.children(&mut cursor);
        // push reversed
        let mut c: Vec<_> = children.collect();
        c.reverse();
        for child in c {
            stack.push((child, depth + 1));
        }
    }
}
