fn main() {
    let mut parser = tree_sitter::Parser::new();
    parser.set_language(&tree_sitter_matlab::LANGUAGE.into()).unwrap();
    let source = b"b.fopen();\ns = serialport('COM3', 9600);\nbt.fwrite(data);\nopengl('data');\nlinprog(x);\n";
    let tree = parser.parse(source, None).unwrap();
    fn print_node(node: tree_sitter::Node, source: &[u8], depth: usize) {
        let text = &source[node.start_byte()..node.end_byte()];
        let text = String::from_utf8_lossy(text);
        let name_field = node.child_by_field_name("name").map(|n| n.kind().to_string());
        println!("{}{} name_field={:?} text={:?}", "  ".repeat(depth), node.kind(), name_field, text);
        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            print_node(child, source, depth + 1);
        }
    }
    print_node(tree.root_node(), source, 0);
}
EOF
